556	      case "allergy_ticket:verify": {
557	        this.playerCorrections.push("verify_substitution");
558	        out.correctionUptake = Math.min(1, out.correctionUptake + 0.5);
559	        for (const [orderId, remaining] of this.prepRemaining) this.prepRemaining.set(orderId, remaining + 1);
