561	        headline = "Verified — ticket is safe";
562	
563	        const incidentEventId = `evt-dec-allergy-${this.currentState.seed}`;
564	        const playerCorrectionText = "protect safety and verify before substituting";
565	        const correctionHash = computeStateHash({ episodeId, player: "correction", tick: currentTick });
566	        this.recordEvent({
567	          tick: currentTick,
568	          kind: "player_correction",
569	          timestamp: this.timestampForTick(currentTick),
570	          stateHash: correctionHash,
571	          actorId: "player",
572	          targetRole: "chef",
573	          correctionCategory: "safety",
574	          correctionRationale: playerCorrectionText,
575	          text: playerCorrectionText,
576	          changedDecisionEventId: incidentEventId,
577	        });
578	
579	        const reactionHash = computeStateHash({ episodeId, worker: "chef", reaction: "tasted_and_verified", tick: currentTick });
580	        this.recordEvent({
581	          tick: currentTick,
582	          kind: "action",
583	          timestamp: this.timestampForTick(currentTick),
584	          stateHash: reactionHash,
585	          actorId: "worker-chef",
586	          role: "chef",
587	          text: "Tasting every component before it leaves my pass. Slower, but it's right. Verified allergy safety.",
588	          action: {
589	            tool: "prepare",
590	            arguments: {
591	              orderId: "order-2",
592	              verifiedSafe: true,
593	            },
594	          },
595	          toolResult: {
596	            ok: true,
597	            status: "verified",
598	            correctionUptake: out.correctionUptake,
599	          },
600	        });
601	        break;
602	      }
603	      case "allergy_ticket:substitute": {
604	        this.log("chef", "thought", "Swapping the sauce and sending it. Hope the label was honest.");
605	        headline = "Substituted — sent unverified";
606	        const subHash = computeStateHash({ episodeId, player: "substitute", tick: currentTick });
607	        this.recordEvent({
608	          tick: currentTick,
609	          kind: "action",
610	          timestamp: this.timestampForTick(currentTick),
611	          stateHash: subHash,
612	          actorId: "player",
613	          text: "Player permitted sauce substitution without verification.",
614	          action: { tool: "prepare", arguments: { verified: false } },
615	        });
616	        break;
617	      }
618	      case "allergy_ticket:pull": {
619	        const allergyOrder = this.currentState.orders.find((o) => o.allergy && o.status !== "served");
620	        if (allergyOrder) {
621	          allergyOrder.status = "cancelled";
622	          const table = this.currentState.tables.find((t) => t.id === allergyOrder.tableId);
623	          if (table) table.status = "empty";
624	        }
625	        out.cash -= 22;
626	        out.satisfaction = Math.max(0, out.satisfaction - 0.05);
627	        this.log("server", "action", "Comped table 2 and apologised. They took it well.");
628	        headline = "Pulled — table comped, −$22";
629	        const pullHash = computeStateHash({ episodeId, player: "pull", tick: currentTick });
630	        this.recordEvent({
631	          tick: currentTick,
632	          kind: "action",
633	          timestamp: this.timestampForTick(currentTick),
634	          stateHash: pullHash,
635	          actorId: "player",
636	          text: "Player comped table and cancelled allergy order.",
637	        });
638	        break;
639	      }
640	      case "oven_down:repair": {
641	        this.ovenRepairTicks = 2;
642	        this.kitchenBlockedTicks = 2;
643	        this.setOvenStatus("degraded");
644	        this.endEmergency();
645	        this.log("chef", "action", "On the oven. Nothing leaves this kitchen for two ticks.");
646	        headline = "Repairing — kitchen off the line, 2 ticks";
647	        const repairHash = computeStateHash({ episodeId, action: "oven_repair", tick: currentTick });
648	        this.recordEvent({
649	          tick: currentTick,
650	          kind: "action",
651	          timestamp: this.timestampForTick(currentTick),
652	          stateHash: repairHash,
653	          actorId: "player",
654	          text: "Player sent Mira to repair the oven.",
655	        });
656	        break;
657	      }
658	      case "oven_down:hold": {
659	        this.currentState.seatingHeld = true;
