661	        headline = "Door held — seating paused";
662	        const holdHash = computeStateHash({ episodeId, action: "oven_hold", tick: currentTick });
663	        this.recordEvent({
664	          tick: currentTick,
665	          kind: "action",
666	          timestamp: this.timestampForTick(currentTick),
667	          stateHash: holdHash,
668	          actorId: "player",
669	          text: "Player held seating during oven emergency.",
670	        });
671	        break;
672	      }
673	      case "oven_down:push": {
674	        this.pushingThrough = true;
675	        this.log("supply_lead", "thought", "Cold dishes only, then. Anything that needs heat is dead weight.");
676	        headline = "Pushing through — cold dishes only";
677	        const pushHash = computeStateHash({ episodeId, action: "oven_push", tick: currentTick });
678	        this.recordEvent({
679	          tick: currentTick,
680	          kind: "action",
681	          timestamp: this.timestampForTick(currentTick),
682	          stateHash: pushHash,
