767	  private applySafetyCorrection(note: string): void {
768	    const out = this.currentState.outcomes;
769	    if (!this.playerCorrections.includes("verify_substitution")) {
770	      this.playerCorrections.push("verify_substitution");
771	      out.correctionUptake = Math.min(1, out.correctionUptake + 0.5);
772	    }
773	    const allergyOrder = this.currentState.orders.find((o) => o.allergy && ACTIVE_ORDER_STATUSES.has(o.status));
774	    if (allergyOrder && allergyOrder.priority !== "high") {
775	      allergyOrder.priority = "high";
776	      if (!this.playerCorrections.includes("prioritize_allergy")) {
777	        this.playerCorrections.push("prioritize_allergy");
778	        out.correctionUptake = Math.min(1, out.correctionUptake + 0.5);
779	      }
780	    }
781	    this.log("you", "player", note);
782	    this.log("chef", "action", "Verified. No swap goes out that I have not tasted.");
783	  }
