1105	    // are an unbudgeted side door and the human/model comparison is theatre.
1106	    if (this.costsManagerAuthority(action) && !this.roundStatus().canAct) {
1107	      this.log("you", "player", `Round ${this.roundNumber} is spent — that will have to wait.`);
