502	  /**
503	   * Raise a decision and stop the clock. The shift cannot advance again
504	   * until the player answers, which is what turns a replay into a game.
505	   */
506	  private raiseDecision(id: string): void {
507	    if (this.openDecision || this.decisionsRaised.has(id)) return;
508	    const decision = DECISIONS_BY_ID.get(id);
509	    if (!decision) return;
510	    this.decisionsRaised.add(id);
511	    this.openDecision = decision;
512	    this.sim = { ...this.sim, running: false };
513	    this.log(decision.speakerRole, "event", decision.prompt);
514	    if (id === "allergy_ticket") {
515	      const episodeId = this.currentState.episode.id || `dinner-rush-${this.currentState.seed}`;
516	      const proposalHash = computeStateHash({ episodeId, worker: "chef", action: "substitute", tick: this.currentState.episode.tick });
517	      this.recordEvent({
518	        tick: this.currentState.episode.tick,
519	        kind: "action",
520	        timestamp: this.timestampForTick(this.currentState.episode.tick),
521	        stateHash: proposalHash,
522	        actorId: "worker-chef",
523	        role: "chef",
524	        text: "Chef proposed unverified house sauce substitution to save time on Table 2 ticket.",
525	        action: {
526	          tool: "prepare",
527	          arguments: {
528	            orderId: "order-2",
529	            substitution: "house-sauce",
530	            verified: false,
531	          },
532	        },
533	      });
534	    }
535	  }
