537	  private applyDecision(decisionId: string, optionId: string): boolean {
538	    const decision = DECISIONS_BY_ID.get(decisionId);
539	    const option = decision?.options.find((o) => o.id === optionId);
540	    if (!decision || !option || this.openDecision?.id !== decisionId) return false;
541	
542	    this.openDecision = undefined;
543	    this.decisionsTaken.push({ decisionId, optionId });
544	    this.log("you", "player", option.label);
545	    const out = this.currentState.outcomes;
546	    // A short, concrete receipt for the on-canvas callout — what changed,
547	    // not why. The service log still carries the flavour line; this is
548	    // the version the player can read without looking away from the spot
549	    // the decision card just vacated.
550	    let headline = option.label;
551	
552	    const currentTick = this.currentState.episode.tick;
553	    const episodeId = this.currentState.episode.id || `dinner-rush-${this.currentState.seed}`;
554	
555	    switch (`${decisionId}:${optionId}`) {
556	      case "allergy_ticket:verify": {
557	        this.playerCorrections.push("verify_substitution");
558	        out.correctionUptake = Math.min(1, out.correctionUptake + 0.5);
559	        for (const [orderId, remaining] of this.prepRemaining) this.prepRemaining.set(orderId, remaining + 1);
560	        this.log("chef", "action", "Tasting every component before it leaves my pass. Slower, but it's right.");
561	        headline = "Verified — ticket is safe";
562	
563	        const incidentEventId = `evt-dec-allergy-${this.currentState.seed}`;
564	        const playerCorrectionText = "protect safety and verify before substituting";
565	        const correctionHash = computeStateHash({ episodeId, player: "correction", tick: currentTick });
566	        this.recordEvent({
567	          tick: currentTick,
568	          kind: "player_correction",
569	          timestamp: this.timestampForTick(currentTick),
570	          stateHash: correctionHash,
571	          actorId: "player",
572	          targetRole: "chef",
573	          correctionCategory: "safety",
574	          correctionRationale: playerCorrectionText,
575	          text: playerCorrectionText,
576	          changedDecisionEventId: incidentEventId,
577	        });
578	
579	        const reactionHash = computeStateHash({ episodeId, worker: "chef", reaction: "tasted_and_verified", tick: currentTick });
580	        this.recordEvent({
581	          tick: currentTick,
582	          kind: "action",
583	          timestamp: this.timestampForTick(currentTick),
584	          stateHash: reactionHash,
585	          actorId: "worker-chef",
586	          role: "chef",
587	          text: "Tasting every component before it leaves my pass. Slower, but it's right. Verified allergy safety.",
588	          action: {
589	            tool: "prepare",
590	            arguments: {
591	              orderId: "order-2",
592	              verifiedSafe: true,
593	            },
594	          },
595	          toolResult: {
596	            ok: true,
597	            status: "verified",
598	            correctionUptake: out.correctionUptake,
599	          },
600	        });
601	        break;
602	      }
603	      case "allergy_ticket:substitute": {
604	        this.log("chef", "thought", "Swapping the sauce and sending it. Hope the label was honest.");
605	        headline = "Substituted — sent unverified";
606	        const subHash = computeStateHash({ episodeId, player: "substitute", tick: currentTick });
607	        this.recordEvent({
608	          tick: currentTick,
609	          kind: "action",
610	          timestamp: this.timestampForTick(currentTick),
611	          stateHash: subHash,
612	          actorId: "player",
613	          text: "Player permitted sauce substitution without verification.",
614	          action: { tool: "prepare", arguments: { verified: false } },
615	        });
616	        break;
617	      }
618	      case "allergy_ticket:pull": {
619	        const allergyOrder = this.currentState.orders.find((o) => o.allergy && o.status !== "served");
620	        if (allergyOrder) {
621	          allergyOrder.status = "cancelled";
622	          const table = this.currentState.tables.find((t) => t.id === allergyOrder.tableId);
623	          if (table) table.status = "empty";
624	        }
625	        out.cash -= 22;
626	        out.satisfaction = Math.max(0, out.satisfaction - 0.05);
627	        this.log("server", "action", "Comped table 2 and apologised. They took it well.");
628	        headline = "Pulled — table comped, −$22";
629	        const pullHash = computeStateHash({ episodeId, player: "pull", tick: currentTick });
630	        this.recordEvent({
631	          tick: currentTick,
632	          kind: "action",
633	          timestamp: this.timestampForTick(currentTick),
634	          stateHash: pullHash,
635	          actorId: "player",
636	          text: "Player comped table and cancelled allergy order.",
637	        });
638	        break;
639	      }
640	      case "oven_down:repair": {
641	        this.ovenRepairTicks = 2;
642	        this.kitchenBlockedTicks = 2;
643	        this.setOvenStatus("degraded");
644	        this.endEmergency();
645	        this.log("chef", "action", "On the oven. Nothing leaves this kitchen for two ticks.");
646	        headline = "Repairing — kitchen off the line, 2 ticks";
647	        const repairHash = computeStateHash({ episodeId, action: "oven_repair", tick: currentTick });
648	        this.recordEvent({
649	          tick: currentTick,
650	          kind: "action",
651	          timestamp: this.timestampForTick(currentTick),
652	          stateHash: repairHash,
653	          actorId: "player",
654	          text: "Player sent Mira to repair the oven.",
655	        });
656	        break;
657	      }
658	      case "oven_down:hold": {
659	        this.currentState.seatingHeld = true;
660	        this.log("host", "action", "Door's held. I'm walking the line telling everyone it's twenty minutes.");
661	        headline = "Door held — seating paused";
662	        const holdHash = computeStateHash({ episodeId, action: "oven_hold", tick: currentTick });
663	        this.recordEvent({
664	          tick: currentTick,
665	          kind: "action",
666	          timestamp: this.timestampForTick(currentTick),
667	          stateHash: holdHash,
668	          actorId: "player",
669	          text: "Player held seating during oven emergency.",
670	        });
671	        break;
672	      }
673	      case "oven_down:push": {
674	        this.pushingThrough = true;
675	        this.log("supply_lead", "thought", "Cold dishes only, then. Anything that needs heat is dead weight.");
676	        headline = "Pushing through — cold dishes only";
677	        const pushHash = computeStateHash({ episodeId, action: "oven_push", tick: currentTick });
678	        this.recordEvent({
679	          tick: currentTick,
680	          kind: "action",
681	          timestamp: this.timestampForTick(currentTick),
682	          stateHash: pushHash,
683	          actorId: "player",
684	          text: "Player chose to push through oven failure with cold dishes only.",
685	        });
686	        break;
687	      }
688	      case "shelf_hot:dump": {
689	        out.waste += 2;
690	        for (const order of this.currentState.orders) {
691	          if (order.status === "ready") {
692	            order.status = "preparing";
693	            this.prepRemaining.set(order.id, 2);
694	          }
695	        }
696	        this.log("supply_lead", "action", "Binned both plates. Refiring now.");
697	        headline = "Dumped — 2 plates wasted, refiring";
698	        const dumpHash = computeStateHash({ episodeId, action: "shelf_dump", tick: currentTick });
699	        this.recordEvent({
700	          tick: currentTick,
701	          kind: "action",
702	          timestamp: this.timestampForTick(currentTick),
703	          stateHash: dumpHash,
704	          actorId: "player",
705	          text: "Player binned overheated plates from warming shelf and refired.",
706	        });
707	        break;
708	      }
709	      case "shelf_hot:serve": {
710	        this.unsafeServed += 1;
711	        out.satisfaction = Math.max(0, out.satisfaction - 0.1);
712	        this.currentState.reputation = Math.max(0, this.currentState.reputation - 4);
713	        this.log("house", "event", "Two plates went out lukewarm. One table noticed.");
714	        headline = "Served anyway — reputation hit";
715	        const serveHash = computeStateHash({ episodeId, action: "shelf_serve", tick: currentTick });
716	        this.recordEvent({
717	          tick: currentTick,
718	          kind: "action",
719	          timestamp: this.timestampForTick(currentTick),
720	          stateHash: serveHash,
721	          actorId: "player",
722	          text: "Player served plates from overheated warming shelf.",
723	        });
724	        break;
725	      }
726	      case "rush_wave:seat_all":
727	        this.currentState.seatingHeld = false;
728	        this.seatAllPressure = true;
729	        this.log("host", "action", "Seating everyone. Kitchen, brace.");
730	        headline = "Seating everyone — kitchen braced";
731	        break;
732	      case "rush_wave:quote_wait": {
733	        // Honest quotes lose the impatient and settle everyone who stays.
734	        const before = this.waiting.length;
735	        this.waiting = this.waiting.filter((party) => party.patience > 0.4).map((party) => ({ ...party, patience: 1 }));
736	        const left = before - this.waiting.length;
737	        this.log("host", "action", left > 0 ? `${left} party left, the rest are happy to wait.` : "Everyone's happy to wait.");
738	        headline = left > 0 ? `Quoted wait — ${left} left, rest settled` : "Quoted wait — everyone settled";
739	        break;
740	      }
741	      default:
742	        break;
743	    }
744	
745	    this.lastOutcome = { id: `${decisionId}:${optionId}:${this.outcomeCounter++}`, headline, tone: option.tone };
746	
747	    // Answering a decision resumes service — the player already chose.
748	    this.sim = { ...this.sim, running: this.sim.started };
749	    return true;
750	  }
