785	  tickMs(): number {
786	    // 0 means "do not auto-advance" — the shell reads it every schedule.
787	    if (!this.sim.started || !this.sim.running || this.openDecision || this.isOver()) return 0;
788	    const cadence = this.preset.tickMs ?? BASE_TICK_MS;
789	    return Math.round(cadence / this.sim.speed);
790	  }
