825	  private debrief(): Debrief {
826	    const out = this.currentState.outcomes;
827	    const safeRate = out.completed > 0 ? out.safeOrders / out.completed : 1;
828	    const lines: DebriefLine[] = [
829	      { label: "Covers served", value: `${out.completed}`, good: out.completed >= 8 },
830	      // Tips are already banked into `cash` when the plate lands.
831	      { label: "Takings", value: `$${Math.round(out.cash)}`, good: out.cash >= this.preset.goal.cash },
832	      { label: "Safe plates", value: `${out.safeOrders}/${out.completed}`, good: safeRate >= 0.95 },
833	      { label: "Walkouts", value: `${this.walkouts}`, good: this.walkouts <= 1 },
834	      { label: "Waste", value: `${out.waste}`, good: out.waste <= 2 },
835	      // Graded on the number the player was shown, not the raw float.
836	      { label: "Reputation", value: `${Math.round(this.currentState.reputation)}%`, good: Math.round(this.currentState.reputation) >= 50 },
837	    ];
838	
839	    const lessons: string[] = [];
840	    if (this.unsafeServed > 0) lessons.push("You sent food you had not verified. One bad plate costs more than a slow night.");
841	    if (this.walkouts > 1) lessons.push(`${this.walkouts} parties walked. Put Vela on the door, or hold it honestly before the queue turns.`);
842	    if (out.completed < 6) lessons.push("The line stalled. Mira only cooks from the kitchen — a second body there halves every prep.");
843	    if (out.waste > 2) lessons.push("Too much food in the bin. Refire early rather than letting the shelf run hot.");
844	    // Tips are the quiet reward for keeping the room calm, and easy to miss
845	    // unless the debrief points at them.
846	    if (out.completed >= 4 && this.tips === 0) {
847	      lessons.push("Nobody tipped. Guests only tip when the room is calm — a queue three deep costs you every gratuity.");
848	    }
849	    if (lessons.length === 0) lessons.push("Clean service. Try it a speed faster, or see how many covers you can take without dropping a safe plate.");
850	
851	    const goal = this.preset.goal;
852	    // The three conditions the verdict is actually computed from, reported
853	    // one by one so "TARGET MISSED" always names which one missed.
854	    const targets: DebriefTarget[] = [
855	      {
856	        label: "Takings",
857	        value: `$${Math.round(out.cash)}`,
858	        requirement: `≥ $${goal.cash}`,
859	        met: out.cash >= goal.cash,
860	      },
861	      {
862	        label: "Walkouts",
863	        value: `${this.walkouts}`,
864	        requirement: `≤ ${goal.maxWalkouts}`,
865	        met: this.walkouts <= goal.maxWalkouts,
866	      },
867	      {
868	        label: "Unverified plates",
869	        value: `${this.unsafeServed}`,
870	        requirement: `≤ ${goal.unsafeAllowed}`,
871	        met: this.unsafeServed <= goal.unsafeAllowed,
872	      },
873	    ];
874	    const met = targets.every((target) => target.met);
875	
876	    const goodCount = lines.filter((line) => line.good).length;
877	    // Sending an unverified allergy plate caps the night no matter the takings.
878	    const grade = this.unsafeServed > 0 ? "D" : goodCount >= 6 ? "A" : goodCount >= 5 ? "B" : goodCount >= 3 ? "C" : "D";
879	    // A miss (or a win) by a hair pulls harder than a clean one either way —
880	    // that's the tension worth naming out loud, not just the number.
881	    const cashGap = out.cash - this.preset.goal.cash;
882	    const nearMissShort = !met && this.unsafeServed === 0 && cashGap < 0 && cashGap >= -this.preset.goal.cash * 0.1;
883	    const nearMissWin = met && cashGap >= 0 && cashGap <= this.preset.goal.cash * 0.08;
884	    const headline = !met
885	      ? this.unsafeServed > 0
886	        ? "You made the money and served a plate you hadn't checked."
887	        : nearMissShort
888	          ? `So close — $${Math.abs(Math.round(cashGap))} short of target. Run it back.`
889	          : "Short of tonight's target."
890	      : nearMissWin
891	        ? "Made target with pennies to spare — that's a real shift."
892	        : grade === "A"
893	          ? "The room never noticed how hard that was."
894	          : grade === "B"
895	            ? "Solid service with a rough patch."
896	            : "You got through it, and the target held.";
897	    return { grade, headline, met, targets, lines, lessons };
898	  }
