1445	      }
1446	    }
1447	
1448	    // 3. The door: parties arrive, wait, get seated, or give up and leave.
1449	    this.runDoor(nextTick);
1450	
1451	    // 4. Worker autonomous baseline behaviors (simple progression for simulation)
1452	    this.progressWorkers();
1453	
1454	    // 4. A repair started by the player finishes on its own.
1455	    if (this.ovenRepairTicks > 0) {
1456	      this.ovenRepairTicks -= 1;
1457	      if (this.ovenRepairTicks === 0) {
