1499	          satisfaction: this.currentState.outcomes.satisfaction,
1500	          waste: this.currentState.outcomes.waste,
1501	          waitTime: this.currentState.outcomes.waitTime,
1502	          completed: this.currentState.outcomes.completed,
1503	          safeOrders: this.currentState.outcomes.safeOrders,
