2237	      this.unsafeServed += 1;
2238	      this.currentState.reputation = Math.max(0, this.currentState.reputation - 6);
2239	      this.log("house", "event", `An unverified ${order.allergy} ticket went out. That is the one you cannot take back.`);
2240	    }
2241	
2242	    const tip = this.waiting.length > 2 ? 0 : Math.round(cash * 0.15);
2243	    this.tips += tip;
2244	    this.currentState.outcomes.cash += tip;
2245	    return { cash, tip };
2246	  }
2247	
2248	
2249	  /**
2250	   * The player's whole action surface for guiding the shift in progress:
2251	   * message a role, move a ticket's priority, call a flagged risky decision,
2252	   * or submit the safety-first correction. Every one of these becomes a real
2253	   * `ActionEnvelope` (`actorType: "player"`) and is validated by
2254	   * `stepEnvelope()` exactly like a worker's own action — the HUD never
2255	   * mutates `currentState` directly.
2256	   */
2257	  submitPlayerIntervention(input: PlayerInterventionInput): { accepted: boolean; state: RestaurantState; error?: ActionError } {
2258	    const targetRole = input.targetRole === "expediter" ? "supply_lead" : input.targetRole;
2259	    const worker = this.currentState.workers.find((w) => w.role === targetRole || (targetRole === "supply_lead" && (w.role as string) === "expediter"));
2260	    const requestId = crypto.randomUUID();
2261	    const base = {
2262	      version: ACTION_VERSION,
2263	      episodeId: this.currentState.episode.id,
2264	      actorId: "player",
2265	      actorType: "player" as const,
2266	      role: targetRole === "everyone" ? "chef" : targetRole,
2267	      tick: this.currentState.episode.tick,
2268	      timestamp: new Date().toISOString(),
2269	      requestId,
2270	      idempotencyKey: `${this.currentState.episode.id}:${requestId}`,
2271	    };
2272	    const reject = (message: string): { accepted: false; state: RestaurantState; error: ActionError } => ({
2273	      accepted: false,
2274	      state: this.state(),
2275	      error: { code: "invalid_arguments", message, retryable: false },
2276	    });
2277	
2278	    /**
2279	     * Answering an open decision is the one intervention the budget does not
2280	     * charge for. A raised decision halts the shift until it is called — the
2281	     * clock stops, so the round cannot close and hand out a fresh envelope.
2282	     * Charging it would deadlock a manager who had already acted this round.
2283	     * It costs no authority either way: the decision is a forced beat both
2284	     * controllers face, not discretionary manager authority.
2285	     */
2286	    const answersOpenDecision =
2287	      input.kind === "approve" && !!this.openDecision && this.openDecision.id === input.decisionId;
2288	
2289	    // The round's envelope is spent, so this one does not land. Recording the
2290	    // refusal rather than dropping it is the point: a manager who tried twice
2291	    // in one round is a different session from one who acted once, and the
2292	    // trace has to be able to tell them apart.
2293	    if (!answersOpenDecision && !this.roundStatus().canAct) {
2294	      const denial: ActionError = this.isOver()
2295	        ? { code: "episode_complete", message: "the shift is over", retryable: false }
2296	        : {
2297	            code: "round_budget_exhausted",
2298	            message: `round ${this.roundNumber} already spent its manager envelope; wait for round ${this.roundNumber + 1}`,
2299	            retryable: false,
2300	          };
2301	      this.recordEvent({
2302	        tick: base.tick,
2303	        kind: "action",
2304	        timestamp: base.timestamp,
2305	        stateHash: computeStateHash({ episodeId: base.episodeId, rejected: input.kind, tick: base.tick, round: this.roundNumber }),
2306	        actorId: "player",
2307	        requestId,
2308	        action: { tool: "rejected", arguments: { kind: input.kind, targetRole } },
2309	        toolResult: { ok: false, error: { code: denial.code, message: denial.message, retryable: denial.retryable } },
2310	      });
2311	      return { accepted: false, state: this.state(), error: denial };
2312	    }
2313	
2314	    let envelope: ActionEnvelope;
2315	    switch (input.kind) {
2316	      case "message":
2317	        if (typeof input.text !== "string" || !input.text.trim()) return reject("message requires non-empty text");
2318	        if (input.text.length > 256) return reject("message text cannot exceed 256 characters");
2319	        if (input.targetRole === "everyone") {
2320	          const targets = this.currentState.workers;
2321	          if (targets.length === 0) return reject("no workers are available");
2322	          let result: { accepted: boolean; state: RestaurantState; error?: ActionError } = { accepted: true, state: this.state() };
2323	          for (const target of targets) {
2324	            result = this.stepEnvelope({
2325	              ...base,
2326	              role: target.role,
2327	              requestId: `${requestId}-${target.role}`,
2328	              idempotencyKey: `${base.idempotencyKey}-${target.role}`,
2329	              tool: "send_message",
2330	              arguments: { to: target.id, text: input.text, priority: input.priority ?? "normal" },
2331	            });
2332	            if (!result.accepted) return result;
2333	          }
2334	          return result;
2335	        }
2336	        if (!worker) return reject(`no worker occupies role ${input.targetRole}`);
2337	        envelope = { ...base, tool: "send_message", arguments: { to: worker.id, text: input.text, priority: input.priority ?? "normal" } };
2338	        break;
2339	      case "priority":
2340	        if (input.targetRole === "everyone") return reject("everyone is only available for messages");
2341	        if (typeof input.orderId !== "string" || !input.orderId) return reject("priority requires an orderId");
2342	        if (input.priority !== "normal" && input.priority !== "high") return reject("priority requires 'normal' or 'high'");
2343	        envelope = { ...base, tool: "coordinate", arguments: { workerId: worker?.id ?? targetRole, orderId: input.orderId, priority: input.priority } };
2344	        break;
2345	      case "approve":
2346	        if (input.targetRole === "everyone") return reject("everyone is only available for messages");
2347	        if (typeof input.decisionId !== "string" || !input.decisionId) return reject("approve requires a decisionId");
2348	        if (typeof input.optionId !== "string" || !input.optionId) return reject("approve requires an optionId");
2349	        envelope = { ...base, tool: "approve", arguments: { decisionId: input.decisionId, optionId: input.optionId } };
2350	        break;
2351	      case "correction":
2352	        if (input.targetRole === "everyone") return reject("everyone is only available for messages");
2353	        envelope = { ...base, tool: "correct", arguments: { note: input.text?.trim() || "Protect safety and verify before substituting." } };
2354	        break;
2355	    }
2356	
2357	    // The charge itself lands in applyRecordedEnvelope, at the same boundary a
2358	    // replay crosses — see there for why it cannot live in this method.
2359	    return this.stepEnvelope(envelope);
2360	  }
2361	}
