286	export function parseDecisionAction(action: string): { decisionId: string; optionId: string } | undefined {
287	  if (!action.startsWith("decide_")) return undefined;
288	  for (const decision of DECISIONS) {
289	    const prefix = `decide_${decision.id}_`;
290	    if (!action.startsWith(prefix)) continue;
291	    const optionId = action.slice(prefix.length);
292	    if (decision.options.some((option) => option.id === optionId)) return { decisionId: decision.id, optionId };
