47	   * for environment-driven runs, which have no model to attribute.
48	   */
49	  model?: TraceV3Model;
50	  /** Monotonic clock for latency. Injectable so tests get deterministic numbers. */
51	  elapsedMs?: () => number;
52	  /** Receives each paced round after its state changes are committed. */
53	  onTick?: (report: OrchestratorTick) => void;
54	}
55	
56	const FALLBACKS: Record<Role | "expediter", { tool: Tool; arguments: Record<string, unknown> }> = {
57	  chef: { tool: "inspect", arguments: { targetId: "oven-1" } },
58	  server: { tool: "inspect", arguments: { targetId: "pass" } },
59	  host: { tool: "update_guest", arguments: { message: "Thank you for your patience; we will seat you as soon as a table is ready." } },
60	  supply_lead: { tool: "inspect", arguments: { targetId: "pass" } },
61	  get expediter() {
62	    return this.supply_lead;
63	  },
64	};
65	
66	/**
67	 * Turns the four Restaurant Arena workers into a paced, autonomous shift.
68	 * It deliberately schedules one role at a time: every observation and action
69	 * remains on the current simulator tick, so an earlier worker cannot make a
70	 * later worker submit a stale envelope.
71	 */
72	export class WorkerOrchestrator {
73	  private readonly roles: readonly Role[];
74	  private readonly tickIntervalMs: number | (() => number);
75	  private timer?: ReturnType<typeof setTimeout>;
76	  private running = false;
77	  private paused = false;
78	  private inFlight = false;
79	  private requestSequence = 0;
80	  private requestEpoch = 0;
81	  private roundTick?: number;
82	  private nextRoleIndex = 0;
83	  private readonly roundTurns: WorkerTurn[] = [];
84	  /** When the current decision round's first worker began, for roundMs. */
85	  private roundStartedAt?: number;
86	
87	  constructor(
88	    private readonly game: RestaurantGame,
89	    private readonly options: WorkerOrchestratorOptions,
90	  ) {
91	    this.roles = options.roles ?? TURN_ORDER;
92	    this.game.setExternalControllers(this.roles);
93	    this.tickIntervalMs = options.tickIntervalMs ?? 1_000;
94	  }
95	
96	  isRunning(): boolean {
97	    return this.running;
98	  }
99	
100	  isPaused(): boolean {
101	    return this.paused;
102	  }
103	
104	  /** Pause before a player intervention; no later worker or tick is started. */
105	  pause(): void {
106	    this.paused = true;
107	    this.requestEpoch += 1;
108	    this.options.client.abort?.();
109	    if (this.timer) clearTimeout(this.timer);
110	    this.timer = undefined;
111	  }
112	
113	  resume(): void {
114	    if (!this.paused) return;
115	    this.paused = false;
116	    if (this.running && !this.inFlight && !this.timer && !this.game.isOver()) void this.pump();
117	  }
118	
119	  /**
120	   * Applies a player change with the worker loop paused. Callers can resume()
121	   * once the player has finished prioritising, approving, or repositioning.
122	   */
123	  intervene<T>(intervention: () => T): T {
124	    this.pause();
125	    return intervention();
126	  }
127	
128	  start(): void {
129	    if (this.game.isOver()) return;
130	    if (this.running) return this.resume();
131	    this.resume();
132	    this.running = true;
133	    void this.pump();
134	  }
135	
136	  stop(): void {
137	    this.running = false;
138	    this.pause();
139	  }
140	
141	  private async pump(): Promise<void> {
142	    if (!this.running || this.paused || this.game.isOver()) {
143	      if (this.game.isOver()) this.running = false;
144	      return;
145	    }
146	    const clock = this.options.elapsedMs ?? (() => Date.now());
147	    const startedAt = clock();
148	    const report = await this.runTick();
149	    this.options.onTick?.(report);
150	    if (!this.running || this.paused || this.game.isOver()) {
151	      if (this.game.isOver()) this.running = false;
152	      return;
153	    }
154	    const interval = typeof this.tickIntervalMs === "function" ? this.tickIntervalMs() : this.tickIntervalMs;
155	    this.timer = setTimeout(() => void this.pump(), Math.max(0, interval - (clock() - startedAt)));
156	  }
157	
158	  /** Execute a complete staff decision round, then advance exactly one game tick. */
159	  async runTick(): Promise<OrchestratorTick> {
160	    if (this.inFlight) throw new Error("worker orchestrator tick already in progress");
161	    this.syncRoundToGameTick();
162	    if (this.paused || this.game.isOver()) {
163	      return { advanced: false, paused: this.paused, complete: this.game.isOver(), turns: [] };
164	    }
165	
166	    this.inFlight = true;
167	    try {
168	      if (this.nextRoleIndex === 0 && this.roundStartedAt === undefined) {
169	        const clock = this.options.elapsedMs ?? (() => Date.now());
170	        this.roundStartedAt = clock();
171	      }
172	      while (this.nextRoleIndex < this.roles.length) {
173	        const role = this.roles[this.nextRoleIndex]!;
174	        if (this.paused || this.game.isOver()) {
175	          return this.partialReport({ role, status: "paused" });
176	        }
177	        const turn = await this.runWorker(role);
178	        if (turn.status === "paused") return this.partialReport(turn);
179	        this.roundTurns.push(turn);
180	        this.nextRoleIndex += 1;
181	      }
182	
183	      // An intervention can arrive while the final model request is awaiting.
184	      if (this.paused || this.game.isOver()) {
185	        return this.partialReport();
186	      }
187	      this.game.step("tick");
188	      const turns = [...this.roundTurns];
189	      this.resetRound();
190	      return { advanced: true, paused: false, complete: this.game.isOver(), turns };
191	    } finally {
192	      this.inFlight = false;
193	    }
194	  }
195	
196	  private syncRoundToGameTick(): void {
197	    const tick = this.game.state().episode.tick;
198	    if (this.roundTick === undefined) {
199	      this.roundTick = tick;
200	    } else if (this.roundTick !== tick) {
201	      this.resetRound();
202	      this.roundTick = tick;
203	    }
204	  }
205	
206	  private resetRound(): void {
207	    this.roundTick = undefined;
208	    this.nextRoleIndex = 0;
209	    this.roundTurns.length = 0;
210	    this.roundStartedAt = undefined;
211	  }
212	
213	  private partialReport(pendingTurn?: WorkerTurn): OrchestratorTick {
214	    return {
215	      advanced: false,
216	      paused: this.paused,
217	      complete: this.game.isOver(),
218	      turns: pendingTurn ? [...this.roundTurns, pendingTurn] : [...this.roundTurns],
219	    };
220	  }
221	
222	  /** Metrics fields shared by the accepted and fallback telemetry passed to stepEnvelope(). */
223	  private metricsTelemetry(latencyMs: number | undefined, roundMs: number | undefined, metrics?: ModelCallMetrics): EnvelopeTelemetry {
224	    return {
225	      ...(latencyMs !== undefined ? { latencyMs } : {}),
226	      ...(roundMs !== undefined ? { roundMs } : {}),
227	      ...(metrics?.queueMs !== undefined ? { queueMs: metrics.queueMs } : {}),
228	      ...(metrics?.providerMs !== undefined ? { providerMs: metrics.providerMs } : {}),
229	      ...(metrics?.inputTokens !== undefined ? { inputTokens: metrics.inputTokens } : {}),
230	      ...(metrics?.outputTokens !== undefined ? { outputTokens: metrics.outputTokens } : {}),
231	      ...(metrics?.cachedInputTokens !== undefined ? { cachedInputTokens: metrics.cachedInputTokens } : {}),
232	      ...(metrics?.finishReason !== undefined ? { finishReason: metrics.finishReason } : {}),
233	    };
234	  }
235	
236	  /** Elapsed time since this decision round's first worker began, measured now. */
237	  private roundMsSoFar(clock: () => number): number | undefined {
238	    return this.roundStartedAt !== undefined ? Math.max(0, clock() - this.roundStartedAt) : undefined;
239	  }
240	
241	  private async runWorker(role: Role): Promise<WorkerTurn> {
242	    const requestEpoch = this.requestEpoch;
243	    const state = this.game.state();
244	    const worker = state.workers.find((candidate) => candidate.role === role);
245	    if (!worker) {
246	      const turn = { role, status: "rejected" as const, error: `no worker for role ${role}` };
247	      this.options.onError?.(turn);
248	      return turn;
249	    }
250	
251	    const observation = this.game.observe(role);
252	    const prompts = buildFullRolePrompt(observation, this.options.promptOptions);
253	    const context: ActionContext = { episodeId: state.episode.id, actorId: worker.id, role, observation };
254	    const clock = this.options.elapsedMs ?? (() => Date.now());
255	    const startedAt = clock();
256	    try {
257	      const action = await this.options.client.act(context, prompts.systemPrompt, prompts.turnPrompt);
258	      const latencyMs = Math.max(0, clock() - startedAt);
259	      const roundMs = this.roundMsSoFar(clock);
260	      const metrics = this.options.client.lastMetrics?.();
261	      if (this.paused || requestEpoch !== this.requestEpoch) return { role, status: "paused", action };
262	      const result = this.game.stepEnvelope(action, { ...this.metricsTelemetry(latencyMs, roundMs, metrics), model: this.options.model });
263	      if (result.accepted) return { role, status: "accepted", action };
264	      // The rejection is already on the trace; the fallback that replaces it
265	      // is recorded separately so both attempts survive in the record.
266	      return this.applyFallback(role, `action rejected: ${result.error?.code ?? "unknown"}`, latencyMs, roundMs, metrics);
267	    } catch (error) {
268	      if (this.paused || requestEpoch !== this.requestEpoch) {
269	        return { role, status: "paused", error: error instanceof Error ? error.message : "model request failed" };
270	      }
271	      return this.applyFallback(
272	        role,
273	        error instanceof Error ? error.message : "model request failed",
274	        Math.max(0, clock() - startedAt),
275	        this.roundMsSoFar(clock),
276	        this.options.client.lastMetrics?.(),
277	      );
278	    }
279	  }
280	
281	  private applyFallback(role: Role, error: string, latencyMs?: number, roundMs?: number, metrics?: ModelCallMetrics): WorkerTurn {
282	    if (this.paused || this.game.isOver()) return { role, status: "paused", error };
283	    const state = this.game.state();
284	    const worker = state.workers.find((candidate) => candidate.role === role);
285	    if (!worker) return { role, status: "rejected", error };
286	    const fallback = FALLBACKS[role];
287	    const requestId = this.options.requestId?.() ?? `fallback-${++this.requestSequence}`;
288	    const action: ActionEnvelope = {
289	      version: ACTION_VERSION,
290	      episodeId: state.episode.id,
291	      actorId: worker.id,
292	      actorType: "worker",
293	      role,
294	      tool: fallback.tool,
295	      arguments: { ...fallback.arguments },
296	      tick: state.episode.tick,
297	      timestamp: (this.options.now?.() ?? new Date()).toISOString(),
298	      requestId,
299	      idempotencyKey: `${state.episode.id}:${requestId}`,
300	    };
301	    const result = this.game.stepEnvelope(action, this.metricsTelemetry(latencyMs, roundMs, metrics));
302	    const turn: WorkerTurn = {
303	      role,
304	      status: result.accepted ? "fallback" : "rejected",
305	      action,
306	      error,
307	    };
308	    this.options.onError?.(turn);
309	    return turn;
310	  }
311	}
