71	    Array.isArray((obj as RestaurantArenaTraceV3).events)
72	  );
73	}
74	
75	function isGame(obj: unknown): obj is RestaurantGame {
76	  return (
77	    typeof obj === "object" &&
78	    obj !== null &&
79	    typeof (obj as RestaurantGame).state === "function" &&
80	    typeof (obj as RestaurantGame).view === "function"
81	  );
82	}
83	
84	export function buildArenaTimeline(source: RestaurantGame | RestaurantArenaTraceV3 | ArenaView): TimelineModel {
85	  const trace = isTrace(source);
86	  const game = isGame(source);
87	  const state = game ? source.state() : trace ? undefined : source;
88	  const events: Pick<TraceV3Event, "tick" | "kind" | "actorId" | "role" | "text" | "payload" | "toolResult" | "action">[] = trace
89	    ? source.events
90	    : game
91	      ? source.getRecordedEvents()
92	      : source.feed.map((entry) => ({
93	          tick: entry.tick,
94	          kind: entry.voice === "you" ? "player_correction" : entry.kind === "action" ? "action" : "message",
95	          actorId: entry.voice === "you" ? "player" : entry.voice === "house" ? "system" : entry.voice,
96	          text: entry.text,
97	        }));
98	  const cards: TimelineCard[] = events.map((event, index) => {
99	    const player = event.actorId === "player" || event.kind === "player_correction";
100	    const correction = event.kind === "player_correction";
101	    const milestone: SequenceMilestone = event.kind === "outcome" ? "outcome" : correction ? "correction" : "original_decision";
102	    const failed = event.toolResult?.ok === false;
103	    return {
104	      id: `recorded-${index}`, milestone, stepIndex: index + 1,
105	      title: event.kind === "outcome" ? "Shift Outcome Metrics" : correction ? "Player Intervention" : "Recorded Event",
106	      role: player ? "player" : event.role ?? "system",
107	      tick: event.tick,
108	      badgeText: failed ? "REJECTED" : event.kind.replaceAll("_", " ").toUpperCase(),
109	      badgeTone: failed ? "danger" : player ? "info" : "neutral",
110	      headline: event.text ?? `${event.actorId ?? "system"}: ${event.action?.tool ?? event.kind}`,
111	      detail: event.toolResult?.error?.message ?? "",
112	    };
113	  });
114	  return {
115	    cards,
116	    milestonesPresented: KEY_SEQUENCE_MILESTONES.filter((milestone) => cards.some((card) => card.milestone === milestone)),
117	    episodeId: trace ? source.episodeId : state!.episode.id,
118	    isComplete: trace ? source.terminal.status === "completed" : state!.episode.phase === "complete",
119	  };
120	}
121	
122	/**
123	 * Render the Timeline Viewer HTML.
124	 * Includes milestone progress strip and scrollable chronological cards.
125	 * Designed to handle large traces gracefully with smooth scrolling and zero visual clipping.
126	 */
127	export function renderTimelineHtml(timeline: TimelineModel): string {
128	  const milestoneLabels: Record<SequenceMilestone, string> = {
129	    original_decision: "1. Original Decision",
130	    correction: "2. Player Correction",
131	    later_probe: "3. Later Probe",
132	    outcome: "4. Shift Outcomes",
133	  };
134	
135	  const stepsHtml = KEY_SEQUENCE_MILESTONES.map((milestone, idx) => {
136	    const isPresented = timeline.milestonesPresented.includes(milestone);
137	    return `
138	      <div class="milestone-step${isPresented ? " is-active" : ""}" data-milestone="${milestone}">
139	        <span class="milestone-dot">${idx + 1}</span>
140	        <span class="milestone-name">${escapeHtml(milestoneLabels[milestone])}</span>
141	      </div>
142	    `;
143	  }).join('<div class="milestone-connector"></div>');
144	
145	  const cardsHtml = timeline.cards
146	    .map((card) => {
147	      const toneClass = `badge-${card.badgeTone}`;
148	      return `
149	        <div class="arena-timeline-card" data-milestone="${card.milestone}" data-step="${card.stepIndex}">
150	          <div class="card-header">
151	            <span class="card-step">#${card.stepIndex}</span>
152	            <span class="card-badge ${toneClass}">${escapeHtml(card.badgeText)}</span>
153	            <span class="card-title">${escapeHtml(card.title)}</span>
154	            <span class="card-tick">Tick ${card.tick}</span>
155	          </div>
156	          <p class="card-headline">${escapeHtml(card.headline)}</p>
157	          <p class="card-detail">${escapeHtml(card.detail)}</p>
158	        </div>
159	      `;
160	    })
161	    .join("");
162	
163	  return `
164	    <div class="arena-timeline" role="region" aria-label="Shift decision and correction timeline" data-sequence="original_decision correction later_probe outcome">
165	      <div class="arena-timeline-header">
166	        <span class="arena-timeline-title">DECISION &amp; CORRECTION TIMELINE</span>
167	        <span class="arena-timeline-badge">${timeline.milestonesPresented.length} MILESTONES</span>
168	      </div>
169	      <div class="arena-timeline-milestones">
170	        ${stepsHtml}
171	      </div>
172	      <div class="arena-timeline-cards" tabindex="0" role="feed" aria-label="Chronological decision cards">
173	        ${cardsHtml}
174	      </div>
175	    </div>
176	  `;
177	}
