5	/** Normalize legacy worker role and ID (expediter -> supply_lead) for initial-state comparison. */
6	export function normalizeLegacyInitialState(state: Record<string, unknown>): Record<string, unknown> {
7	  const workers = Array.isArray(state.workers)
8	    ? state.workers.map((w: any) => {
9	        const isLegacyRole = w?.role === "expediter";
10	        const isLegacyId = w?.id === "worker-expediter";
11	        if (isLegacyRole || isLegacyId) {
12	          return {
13	            ...w,
14	            id: isLegacyId ? "worker-supply_lead" : w.id,
15	            role: isLegacyRole ? "supply_lead" : w.role,
16	          };
17	        }
18	        return w;
19	      })
20	    : state.workers;
