24	function toLegacyWorkerRepresentation(obj: unknown): unknown {
25	  if (obj === null || obj === undefined || typeof obj !== "object") return obj;
26	  if (Array.isArray(obj)) return obj.map(toLegacyWorkerRepresentation);
27	  const record = obj as Record<string, unknown>;
28	  const res: Record<string, unknown> = {};
29	  for (const [k, v] of Object.entries(record)) {
30	    if (k === "workers" && Array.isArray(v)) {
