72	    if (game.state().episode.tick !== input.tick) throw new Error(`Input ${index}: tick mismatch`);
73	    switch (input.kind) {
74	      case "step":
75	        if (!game.actions.includes(input.action)) throw new Error(`Input ${index}: unknown game action`);
