85	        throw new Error(`Input ${index}: checkpoint mismatch`);
86	      }
87	    }
88	    if (input.restaurantStateHash !== undefined && computeStateHash(game.state()) !== input.restaurantStateHash) {
89	      if (computeStateHash(toLegacyWorkerRepresentation(game.state())) !== input.restaurantStateHash) {
90	        throw new Error(`Input ${index}: RestaurantState checkpoint mismatch`);
91	      }
