arguments.content:
/**
 * Standing corrections, as state the floor is actually bound by.
 *
 * A mid-shift correction used to be a line in the service log and an event in
 * the trace: it moved a counter once, on the tick it was issued, and by the
 * next turn nothing on the floor remembered it. A *standing directive* is the
 * same instruction kept in force — it names the roles it binds and the tickets
 * it covers, and it keeps binding them on every later turn until the manager
 * explicitly lifts it.
 *
 * It is deliberately not part of `RestaurantState`: that contract is
 * schema-locked and published (see contracts/restaurant-arena-state-*.json).
 * Directives live in the engine's own replay state instead, read through
 * `RestaurantGame.activeDirectives()` / `directivesFor(role)`, and are enforced
 * at the action boundary in `stepEnvelope()`.
 */

import type { Role } from "./types.js";

/**
 * Same vocabulary as `TraceV3Event.correctionCategory`, so a directive and the
 * `player_correction` event that issued it never disagree about what kind of
 * correction it was.
 */
export type DirectiveCategory = "safety" | "priority" | "quality" | "pace";

export interface StandingDirective {
  /** `dir-1`, `dir-2`, … in issue order. */
  readonly id: string;
  readonly category: DirectiveCategory;
  /** The manager's rationale, as issued. */
  readonly note: string;
  /** Which roles this correction keeps binding. */
  readonly roles: readonly Role[];
  /**
   * The tickets the correction is scoped to. Empty means "every ticket that
   * carries a guest constraint" — a safety correction issued while no allergy
   * ticket is live still binds the next one, rather than binding nothing.
   */
  readonly orderIds: readonly string[];
  readonly issuedAtTick: number;
  /** 1-based issue order, so a role's corrections can be listed as issued. */
  readonly sequence: number;
  /** Set when the manager explicitly lifted it; absent while it stands. */
  readonly liftedAtTick?: number;
}

/** The shape of an order a directive's scope is checked against. */
export interface DirectiveOrderScope {
  readonly id: string;
  readonly allergy?: string;
}

/** Which roles each kind of correction binds when it is issued. */
export const DIRECTIVE_ROLES: Readonly<Record<DirectiveCategory, readonly Role[]>> = {
  // The chef executes the verification; the supply lead has to protect the
  // time it costs at the pass rather than pushing the kitchen through it.
  safety: ["chef", "supply_lead"],
  priority: ["chef", "supply_lead"],
  quality: ["chef", "supply_lead"],
  // Holding the door is the host's call to carry out and the server's to
  // explain to the tables already seated.
  pace: ["host", "server"],
};

export function isDirectiveInForce(directive: StandingDirective): boolean {
  return directive.liftedAtTick === undefined;
}

export function directiveTargetsRole(directive: StandingDirective, role: Role): boolean {
  return directive.roles.includes(role);
}

/** Whether `order` is one of the tickets this correction covers. */
export function directiveCoversOrder(directive: StandingDirective, order: DirectiveOrderScope): boolean {
  if (directive.orderIds.length > 0) return directive.orderIds.includes(order.id);
  return order.allergy !== undefined;
}

/** A defensive copy: callers read directives, they never edit them in place. */
export function cloneDirective(directive: StandingDirective): StandingDirective {
  return {
    ...directive,
    roles: [...directive.roles],
    orderIds: [...directive.orderIds],
  };
}

/**
 * Two corrections of the same kind over the same tickets are one standing
 * instruction, not two. Re-issuing it (the panel button pressed twice, a
 * decision answered the same way again) must not stack duplicates that then
 * have to be lifted one by one.
 */
export function sameDirectiveScope(a: readonly string[], b: readonly string[]): boolean {
  if (a.length !== b.length) return false;
  const left = [...a].sort();
  const right = [...b].sort();
  return left.every((id, index) => id === right[index]);
}

/** The word a worker would use to name this correction to a teammate. */
const CATEGORY_MENTIONS: Readonly<Record<DirectiveCategory, RegExp>> = {
  safety: /\bsafet(y|ies)\b/i,
  priority: /\bpriorit(y|ies|ise|ize|ised|ized|ising|izing)\b/i,
  quality: /\bqualit(y|ies)\b/i,
  pace: /\bpac(e|ed|es|ing)\b/i,
};

/** Whether `text` names this correction's category, e.g. relaying it at the pass. */
export function mentionsDirectiveCategory(text: string, category: DirectiveCategory): boolean {
  return CATEGORY_MENTIONS[category].test(text);
}

