591	    // A short, concrete receipt for the on-canvas callout — what changed,
592	    // not why. The service log still carries the flavour line; this is
593	    // the version the player can read without looking away from the spot
594	    // the decision card just vacated.
595	    let headline = option.label;
596	
597	    const currentTick = this.currentState.episode.tick;
598	    const episodeId = this.currentState.episode.id || `dinner-rush-${this.currentState.seed}`;
599	
600	    switch (`${decisionId}:${optionId}`) {
601	      case "allergy_ticket:verify": {
602	        this.playerCorrections.push("verify_substitution");
603	        out.correctionUptake = Math.min(1, out.correctionUptake + 0.5);
604	        for (const [orderId, remaining] of this.prepRemaining) this.prepRemaining.set(orderId, remaining + 1);
605	        this.log("chef", "action", "Tasting every component before it leaves my pass. Slower, but it's right.");
606	        headline = "Verified — ticket is safe";
607	
608	        const incidentEventId = `evt-dec-allergy-${this.currentState.seed}`;
609	        const playerCorrectionText = "protect safety and verify before substituting";
610	        const correctionHash = computeStateHash({ episodeId, player: "correction", tick: currentTick });
611	        this.recordEvent({
612	          tick: currentTick,
613	          kind: "player_correction",
614	          timestamp: this.timestampForTick(currentTick),
615	          stateHash: correctionHash,
616	          actorId: "player",
617	          targetRole: "chef",
618	          correctionCategory: "safety",
619	          correctionRationale: playerCorrectionText,
620	          text: playerCorrectionText,
621	          changedDecisionEventId: incidentEventId,
622	        });
623	
624	        const reactionHash = computeStateHash({ episodeId, worker: "chef", reaction: "tasted_and_verified", tick: currentTick });
625	        this.recordEvent({
626	          tick: currentTick,
627	          kind: "action",
628	          timestamp: this.timestampForTick(currentTick),
629	          stateHash: reactionHash,
630	          actorId: "worker-chef",
631	          role: "chef",
632	          text: "Tasting every component before it leaves my pass. Slower, but it's right. Verified allergy safety.",
633	          action: {
634	            tool: "prepare",
635	            arguments: {
636	              orderId: "order-2",
637	              verifiedSafe: true,
638	            },
639	          },
