641	            ok: true,
642	            status: "verified",
643	            correctionUptake: out.correctionUptake,
644	          },
645	        });
646	        break;
647	      }
648	      case "allergy_ticket:substitute": {
649	        this.log("chef", "thought", "Swapping the sauce and sending it. Hope the label was honest.");
650	        headline = "Substituted — sent unverified";
651	        const subHash = computeStateHash({ episodeId, player: "substitute", tick: currentTick });
652	        this.recordEvent({
653	          tick: currentTick,
