1818	  private applyRecordedEnvelope(envelope: ActionEnvelope, telemetry?: EnvelopeTelemetry) {
1819	    const cached = this.idempotencyCache.get(envelope.idempotencyKey);
1820	    if (cached) return cached;
1821	
1822	    // The manager's round budget is enforced here rather than in
1823	    // submitPlayerIntervention because this is the boundary a replay crosses:
1824	    // replay re-applies recorded envelopes directly, so a check made further
1825	    // up would be missing on the way back through and the two runs would
1826	    // diverge on the first envelope the budget refused. It also means a
1827	    // direct stepEnvelope() caller cannot walk around the budget.
1828	    //
1829	    // `undefined` means this envelope draws on no budget at all: a worker's
1830	    // own action, or a manager answering a raised decision.
1831	    const managerKey =
1832	      envelope.actorType === "player" && envelope.tool !== "approve"
1833	        ? this.managerRequestKey(envelope.requestId)
1834	        : undefined;
1835	    // One instruction to the whole floor arrives as four envelopes sharing a
1836	    // request stem. The first is charged; the rest are the same exercise of
1837	    // authority and neither charge nor re-check.
1838	    const alreadyCharged = managerKey !== undefined && managerKey === this.lastChargedManagerRequest;
1839	
1840	    if (managerKey !== undefined && !alreadyCharged && !this.roundStatus().canAct) {
1841	      const error: ActionError = {
1842	        code: "round_budget_exhausted",
1843	        message: `round ${this.roundNumber} already spent its manager envelope; wait for round ${this.roundNumber + 1}`,
1844	        retryable: false,
1845	      };
1846	      this.journalRejectedEnvelope(envelope, error, telemetry);
1847	      return { accepted: false, state: this.state(), error };
1848	    }
1849	
1850	    this.pendingTelemetry = telemetry;
1851	    try {
1852	      const result = this.applyEnvelope(envelope);
1853	      if (!result.accepted && result.error) {
1854	        this.journalRejectedEnvelope(envelope, result.error, telemetry);
1855	        return result;
1856	      }
1857	      // Charged only once the action actually landed. A ticket that turned out
1858	      // to be cancelled, or an order id that matches nothing, costs the manager
1859	      // nothing — they did not get to change anything with it.
1860	      if (managerKey !== undefined && !alreadyCharged) {
1861	        this.lastChargedManagerRequest = managerKey;
1862	        this.spendManagerEnvelope();
1863	      }
1864	      return result;
1865	    } finally {
1866	      this.pendingTelemetry = undefined;
1867	    }
1868	  }
1869	
1870	  /** The rejection as the graders read it: one event, `toolResult.ok` false. */
1871	  private journalRejectedEnvelope(
1872	    envelope: ActionEnvelope,
1873	    error: ActionError,
1874	    telemetry?: EnvelopeTelemetry,
1875	  ): void {
1876	    this.recordEvent({
1877	      tick: this.currentState.episode.tick,
1878	      kind: "action",
1879	      timestamp: envelope.timestamp || this.timestampForTick(this.currentState.episode.tick),
1880	      stateHash: computeStateHash({
1881	        episodeId: envelope.episodeId,
1882	        requestId: envelope.requestId,
1883	        actorId: envelope.actorId,
1884	        tool: envelope.tool,
1885	        rejected: error.code,
1886	        tick: this.currentState.episode.tick,
1887	      }),
1888	      actorId: envelope.actorId,
1889	      role: envelope.role,
1890	      requestId: envelope.requestId,
1891	      idempotencyKey: envelope.idempotencyKey,
1892	      ...(telemetry?.model ? { model: telemetry.model } : {}),
1893	      text: `${STAFF[envelope.role]?.name ?? envelope.role} was refused ${envelope.tool}: ${error.message}`,
1894	      action: { tool: envelope.tool, arguments: envelope.arguments },
1895	      toolResult: {
1896	        ok: false,
1897	        ...telemetryToolResultFields(telemetry),
1898	        error: { code: error.code, message: error.message, retryable: error.retryable },
1899	      },
1900	    });
1901	  }
1902	
1903	  private applyEnvelope(envelope: ActionEnvelope): { accepted: boolean; state: RestaurantState; error?: ActionError } {
1904	    // Idempotency check
1905	    const cached = this.idempotencyCache.get(envelope.idempotencyKey);
1906	    if (cached) return cached;
1907	
1908	    // Staleness
1909	    if (envelope.tick !== this.currentState.episode.tick) {
1910	      const err: ActionError = { code: "stale_tick", message: "action tick does not match the current tick", retryable: true };
1911	      const res = { accepted: false, state: this.state(), error: err };
1912	      this.idempotencyCache.set(envelope.idempotencyKey, res);
1913	      return res;
1914	    }
1915	
1916	    // Episode completion
1917	    if (this.isOver()) {
1918	      const err: ActionError = { code: "episode_complete", message: "the episode has already ended", retryable: false };
1919	      const res = { accepted: false, state: this.state(), error: err };
1920	      this.idempotencyCache.set(envelope.idempotencyKey, res);
1921	      return res;
1922	    }
1923	
1924	    // Tool permission: a worker is bound to its role's tool list; the player
1925	    // intervenes through a separate, fixed set no worker role is ever
1926	    // granted (see PLAYER_TOOLS) — the manager overrules the floor, but only
1927	    // through the same validated boundary, never a direct state mutation.
1928	    if (envelope.actorType === "worker") {
