21	/**
22	 * The arena build a trace was recorded against. Kept in step with the package
23	 * version by hand: the overlay bundles this module for the browser, where
24	 * reading package.json at runtime is not available.
25	 */
26	export const ARENA_ENV_VERSION = "0.3.4" as const;
27	
28	export type TraceEventKind =
29	  | "observation"
30	  | "action"
31	  | "player_correction"
32	  | "message"
33	  | "outcome"
34	  | "inspection"
35	  | "hold"
36	  | "hold_cleared"
37	  | "verification_request"
38	  | "verification_response"
39	  | "escalation"
40	  | "handoff"
41	  | "supply_order"
42	  | "supply_delivered"
43	  | "stockout";
44	
45	export type TraceV3Role = Role | "expediter";
46	
47	export interface TraceV3Model {
48	  provider: string;
49	  name: string;
50	  version?: string;
51	}
52	
53	export interface TraceV3Subject {
54	  kind: "order" | "ingredient" | "equipment" | "handoff";
55	  id: string;
56	}
57	
58	/**
59	 * The three keys a grader sorts on. Everything a tool returns beyond them
60	 * (`status: "verified"`, counts, ids) rides alongside untouched.
61	 */
62	export interface TraceV3ToolResult extends Record<string, unknown> {
63	  /** False on every rejected or failed call. Filter on this to select failures. */
64	  ok?: boolean;
65	  /** Model or tool round trip. Absent when no call stood behind the event. */
66	  latencyMs?: number;
67	  /** Time spent waiting for a shared account's request budget before the provider call started. */
68	  queueMs?: number;
69	  /** The provider call itself, excluding queueMs. Absent when the transport cannot separate the two. */
70	  providerMs?: number;
71	  /** Elapsed time since this decision round started, through this worker's own completion. */
72	  roundMs?: number;
73	  /** Absent fields below mean the provider did not report that count, not that it was zero. */
74	  inputTokens?: number;
75	  outputTokens?: number;
76	  cachedInputTokens?: number;
77	  finishReason?: string;
78	  error?: { code: string; message: string; retryable?: boolean } | null;
79	}
80	
81	export interface TraceV3Deletion {
82	  requestId: string | null;
83	  status: "retained" | "requested" | "deleted";
84	}
85	
86	export interface TraceV3Event {
87	  tick: number;
88	  /**
89	   * The decision round this event happened in (#262). Round *r* advances
90	   * ticks 2r-1 and 2r, so a reviewer can line a manager action up against the
91	   * worker turns it shaped without counting ticks by hand.
92	   */
93	  round?: number;
94	  kind: TraceEventKind;
95	  timestamp: string;
96	  stateHash: string;
97	  actorId?: string;
98	  role?: TraceV3Role;
