// ---------------------------------------------------------------------------
// Standing corrections
//
// Issuing a correction used to be a line in the log and one bump of a
// counter. These methods are the part that makes it stick: `issueDirective`
// puts it in force, `activeDirectives`/`directivesFor` are how the floor and
// the graders read what is still in force, and lifting is the only way it
// stops.
// ---------------------------------------------------------------------------

/**
 * Put a correction in force, or hand back the one already standing over the
 * same tickets. Saying the same thing twice is one instruction, not two —
 * otherwise a manager who restated a correction would have to lift it as
 * many times as they said it.
 */
private issueDirective(input: {
  category: DirectiveCategory;
  note: string;
  orderIds?: readonly string[];
  roles?: readonly Role[];
}): StandingDirective {
  const orderIds = [...(input.orderIds ?? [])];
  const standing = this.directives.find(
    (directive) =>
      isDirectiveInForce(directive) &&
      directive.category === input.category &&
      sameDirectiveScope(directive.orderIds, orderIds),
  );
  if (standing) return standing;

  const sequence = ++this.directiveCounter;
  const directive: StandingDirective = {
    id: `dir-${sequence}`,
    category: input.category,
    note: input.note,
    roles: [...(input.roles ?? DIRECTIVE_ROLES[input.category])],
    orderIds,
    issuedAtTick: this.currentState.episode.tick,
    sequence,
  };
  this.directives.push(directive);
  return directive;
}

/**
 * The tickets a safety correction is scoped to when it is issued. Empty when
 * no constrained ticket is live — which `directiveCoversOrder` reads as "the
 * next one that carries a guest constraint", so correcting the kitchen early
 * still binds the ticket that arrives later.
 */
private constrainedOrderIds(): string[] {
  return this.currentState.orders
    .filter((order) => order.allergy && ACTIVE_ORDER_STATUSES.has(order.status))
    .map((order) => order.id);
}

/** Mark one directive lifted, in place, and hand back the lifted copy. */
private standDown(directive: StandingDirective): StandingDirective {
  const lifted: StandingDirective = { ...cloneDirective(directive), liftedAtTick: this.currentState.episode.tick };
  this.directives[this.directives.indexOf(directive)] = lifted;
  return lifted;
}

/** Lift every correction in force in one category — reopening the door lifts the hold. */
private liftDirectivesInCategory(category: DirectiveCategory): StandingDirective[] {
  const lifted: StandingDirective[] = [];
  for (const directive of [...this.directives]) {
    if (isDirectiveInForce(directive) && directive.category === category) lifted.push(this.standDown(directive));
  }
  return lifted;
}

/** Every correction currently in force, in issue order. */
activeDirectives(): StandingDirective[] {
  return this.directives
    .filter(isDirectiveInForce)
    .sort((a, b) => a.sequence - b.sequence)
    .map(cloneDirective);
}

/**
 * A role's corrections in issue order: what this body is still bound by on
 * this turn, which is the whole point of a correction that sticks. Pass
 * `includeLifted` to read the ones that have been stood down as well.
 */
directivesFor(role: Role, options?: { includeLifted?: boolean }): StandingDirective[] {
  return this.directives
    .filter((directive) => directiveTargetsRole(directive, role))
    .filter((directive) => options?.includeLifted === true || isDirectiveInForce(directive))
    .sort((a, b) => a.sequence - b.sequence)
    .map(cloneDirective);
}

