if (envelope.tool === "correct") {
  // `correct` with a `lift` argument stands a correction down instead of
  // issuing one — the same authority, exercised the other way, through the
  // same journalled boundary.
  const liftId = liftedDirectiveId(envelope);
  if (liftId !== undefined) {
    const directive = this.directives.find((candidate) => candidate.id === liftId);
    if (!directive) {
      const err: ActionError = { code: "unknown_entity", message: `unknown standing correction ${liftId}`, retryable: false };
      const res = { accepted: false, state: this.state(), error: err };
      this.idempotencyCache.set(envelope.idempotencyKey, res);
      return res;
    }
    if (!isDirectiveInForce(directive)) {
      const err: ActionError = {
        code: "invalid_state",
        message: `standing correction ${liftId} was already lifted at tick ${directive.liftedAtTick}`,
        retryable: false,
      };
      const res = { accepted: false, state: this.state(), error: err };
      this.idempotencyCache.set(envelope.idempotencyKey, res);
      return res;
    }
    const lifted = this.standDown(directive);
    if (lifted.category === "pace") this.currentState.seatingHeld = false;
    const note = typeof envelope.arguments.note === "string" ? envelope.arguments.note.trim() : "";
    this.log("you", "player", note || `Lifted the standing ${lifted.category} correction.`);
    for (const role of lifted.roles) {
      this.log(role, "action", `Understood — the ${lifted.category} correction is stood down.`);
    }
  } else {
    const note = envelope.arguments.note as string | undefined;
    if (typeof note !== "string" || !note.trim()) {
      const err: ActionError = { code: "invalid_arguments", message: "correct requires non-empty string 'note'", retryable: false };
      const res = { accepted: false, state: this.state(), error: err };
      this.idempotencyCache.set(envelope.idempotencyKey, res);
      return res;
    }
    this.applySafetyCorrection(note);
  }
}

