/**
 * The standing correction a `correct` envelope is lifting, if it is a lift at
 * all. A lift is not a new instruction, so it neither draws on the round's
 * envelope nor journals as another correction.
 */
function liftedDirectiveId(envelope: ActionEnvelope): string | undefined {
  if (envelope.tool !== "correct") return undefined;
  const lift = envelope.arguments.lift;
  return typeof lift === "string" && lift.trim() ? lift.trim() : undefined;
}

