const verified = envelope.arguments.verified === true || envelope.arguments.verifiedSafe === true;

// Where the correction actually binds. A safety correction covering this
// ticket means the swap gets checked or it does not go out: the refusal
// lands here, at the boundary, not in a report written afterwards.
const substitution = envelope.arguments.substitution;
const swapping =
  (typeof substitution === "string" && substitution.trim().length > 0) ||
  envelope.arguments.verified === false ||
  envelope.arguments.verifiedSafe === false;
if (!verified && swapping) {
  const covering = this.directivesFor(envelope.role).find(
    (directive) => directive.category === "safety" && directiveCoversOrder(directive, order),
  );
  if (covering) {
    return {
      code: "unsafe_action",
      message: `standing safety correction ${covering.id} covers ${orderId}: verify the substitution before firing it`,
      retryable: false,
    };
  }
}

if (verified) this.verifiedOrderIds.add(order.id);

