      episodeId: game.state().episode.id,
      actorId: "player",
      actorType: "player",
      role: "chef",
      tool: "send_message",
      arguments: { to: "worker-chef", text: oversized, priority: "normal" },
      tick: 0,
      timestamp: new Date().toISOString(),
      requestId: "req-oversized-envelope",

