import { RestaurantGame } from "./src/games/restaurant-arena/restaurant-game.js";
const g = new RestaurantGame(218220);
g.step("sim_start");
for (let i=0;i<6;i++) g.step("tick");
console.log("waiting", g.view().waiting?.map(p=>p.id), "tick", g.state().episode.tick);
g.step("hold_seating");
console.log("dirs", g.activeDirectives().map(d=>d.id+":"+d.category), "held", g.state().seatingHeld);
console.log("host dirs", g.directivesFor("host").length, "server", g.directivesFor("server").length, "chef", g.directivesFor("chef").length);
const party = g.view().waiting?.[0];
const table = g.state().tables.find(t=>t.status==="empty");
const mk = (over:any) => ({version:"restaurant-arena-action/v1",episodeId:g.state().episode.id,actorType:"worker" as const,tick:g.state().episode.tick,timestamp:"2026-09-02T00:00:00Z",...over});
let r = g.stepEnvelope(mk({actorId:"worker-host",role:"host",tool:"seat",arguments:{tableId:table?.id ?? "table-1",partyId:party?.id ?? "party-1"},requestId:"r1",idempotencyKey:"k1"}));
console.log("seat while held:", r.accepted, r.error);
// update_guest credit
r = g.stepEnvelope(mk({actorId:"worker-host",role:"host",tool:"update_guest",arguments:{message:"Twenty minute wait, honest quote."},requestId:"r2",idempotencyKey:"k2"}));
console.log("update_guest", r.accepted, g.state().outcomes.correctionUptake);
// lift
const id = g.activeDirectives()[0].id;
const lifted = g.liftDirective(id, "Kitchen caught up — door is open again.");
