console.log("includeLifted", g.directivesFor("host",{includeLifted:true}).map(d=>d.id+":"+d.liftedAtTick));
r = g.stepEnvelope(mk({actorId:"worker-host",role:"host",tool:"seat",arguments:{tableId:table?.id ?? "table-1",partyId:party?.id ?? "party-1"},requestId:"r3",idempotencyKey:"k3"}));
console.log("seat after lift:", r.accepted, r.error);
console.log("relift", g.liftDirective(id).error?.code, g.liftDirective("dir-99").error?.code);
' 2>&1 | tail -14

