import { describe, expect, it } from "bun:test";
import { RestaurantGame } from "./restaurant-game.js";
import { replayArenaTrace } from "./replay.js";
import type { ActionEnvelope, Role, Tool } from "./types.js";

const SEED = 218220;

/** A worker envelope on the tick the game is actually on. */
function workerEnvelope(
  game: RestaurantGame,
  actor: { role: Role; tool: Tool; arguments: Record<string, unknown> },
  key: string,
): ActionEnvelope {
  return {
    version: "restaurant-arena-action/v1",
    episodeId: game.state().episode.id,
    actorId: `worker-${actor.role}`,
    actorType: "worker",
    role: actor.role,
    tool: actor.tool,
    arguments: actor.arguments,
    tick: game.state().episode.tick,
    timestamp: "2026-09-05T18:00:00.000Z",
    requestId: `req-${key}`,
    idempotencyKey: `idem-${key}`,
  };
}

/** The shift up to the point the warming shelf starts running warm. */
function playToProbeTrigger(game: RestaurantGame): void {
  game.step("sim_start");
  while (game.probeReport().triggered === false && game.state().episode.tick < 30) game.step("tick");
}

describe("standing corrections keep binding until they are lifted", () => {
  it("keeps a correction in force on every later turn", () => {
    const game = new RestaurantGame(SEED);
    game.step("sim_start");
    game.step("verify_substitution");

    const [issued] = game.activeDirectives();
    expect(issued?.category).toBe("safety");
    expect(issued?.roles).toEqual(["chef", "supply_lead"]);
    expect(issued?.orderIds).toEqual(["order-2"]);
    expect(issued?.issuedAtTick).toBe(0);
    expect(issued?.liftedAtTick).toBeUndefined();

    // Six turns later it is still the chef's instruction — the whole point.
    for (let tick = 0; tick < 6; tick += 1) game.step("tick");
    expect(game.activeDirectives().map((directive) => directive.id)).toEqual([issued!.id]);
    expect(game.directivesFor("chef").map((directive) => directive.id)).toEqual([issued!.id]);
  });

  it("lists a role's corrections in issue order and only that role's", () => {
    const game = new RestaurantGame(SEED);
    game.step("sim_start");
    game.step("verify_substitution");
    game.step("tick");
    game.step("tick");
    game.step("hold_seating");
    game.step("tick");
    game.step("tick");
    game.step("prioritize_allergy");

    expect(game.activeDirectives().map((directive) => [directive.id, directive.category])).toEqual([
      ["dir-1", "safety"],
      ["dir-2", "pace"],
      ["dir-3", "priority"],
    ]);
    // The kitchen is bound by the safety and priority corrections, in the order
    // they were issued; holding the door is the front of house's to carry out.
    expect(game.directivesFor("chef").map((directive) => directive.id)).toEqual(["dir-1", "dir-3"]);
    expect(game.directivesFor("supply_lead").map((directive) => directive.id)).toEqual(["dir-1", "dir-3"]);
    expect(game.directivesFor("host").map((directive) => directive.id)).toEqual(["dir-2"]);
    expect(game.directivesFor("server").map((directive) => directive.id)).toEqual(["dir-2"]);
  });

  it("issues one standing correction however many times the manager says it", () => {
    const game = new RestaurantGame(SEED);
    game.step("sim_start");
    game.step("verify_substitution");
    game.step("tick");
    game.step("tick");
    game.step("verify_substitution");
    expect(game.activeDirectives()).toHaveLength(1);
  });

  it("stops binding only when it is explicitly lifted", () => {
    const game = new RestaurantGame(SEED);
    game.step("sim_start");
    game.step("verify_substitution");

    const lift = game.liftDirective("dir-1", "Ticket is out. Stand the verification down.");
    expect(lift.accepted).toBe(true);
    expect(game.activeDirectives()).toEqual([]);
    expect(game.directivesFor("chef")).toEqual([]);

    const [lifted] = game.directivesFor("chef", { includeLifted: true });
    expect(lifted?.id).toBe("dir-1");
    expect(lifted?.liftedAtTick).toBe(0);
  });

  it("refuses to lift a correction twice, or one that was never issued", () => {
    const game = new RestaurantGame(SEED);
    game.step("sim_start");
    game.step("verify_substitution");
    expect(game.liftDirective("dir-1").accepted).toBe(true);

    const again = game.liftDirective("dir-1");
    expect(again.accepted).toBe(false);
    expect(again.error?.code).toBe("invalid_state");

    const unknown = game.liftDirective("dir-9");
    expect(unknown.accepted).toBe(false);
    expect(unknown.error?.code).toBe("unknown_entity");
  });

  it("lets a manager lift in the same round they issued in", () => {
    const game = new RestaurantGame(SEED);
    game.step("sim_start");
    game.step("verify_substitution");
    // The round's one envelope is spent, but withdrawing an instruction takes
    // authority away rather than exercising more of it.
    expect(game.roundStatus().canAct).toBe(false);
    expect(game.liftDirective("dir-1").accepted).toBe(true);
    expect(game.activeDirectives()).toEqual([]);
  });

  it("survives a deterministic replay still in force", () => {
    const game = new RestaurantGame(SEED);
    game.step("sim_start");
    game.step("verify_substitution");
    game.step("tick");
    game.step("tick");

    const replayed = replayArenaTrace(game.captureTrace({ runKind: "synthetic" }));
    expect(replayed.checkpointState()).toEqual(game.checkpointState());
    expect(replayed.activeDirectives()).toEqual(game.activeDirectives());
    expect(replayed.directivesFor("chef").map((directive) => directive.id)).toEqual(["dir-1"]);
  });
});

describe("standing corrections bind at the action boundary", () => {
  it("refuses an unverified substitution on a ticket the safety correction covers", () => {
    const game = new RestaurantGame(SEED);
    game.step("sim_start");
    game.step("verify_substitution");

    const before = game.state();
    const result = game.stepEnvelope(
      workerEnvelope(game, { role: "chef", tool: "prepare", arguments: { orderId: "order-2", substitution: "house-sauce" } }, "swap"),
    );
    expect(result.accepted).toBe(false);
    expect(result.error?.code).toBe("unsafe_action");
    expect(result.error?.message).toContain("dir-1");
    expect(game.state()).toEqual(before);

    // The refusal reaches the trace as a failed call, not as silence.
    const refusal = game.captureTrace({ runKind: "synthetic" }).events.at(-1);
    expect(refusal?.toolResult?.ok).toBe(false);
    expect(refusal?.toolResult?.error?.code).toBe("unsafe_action");
  });

  it("lets the same swap through once the chef verifies it", () => {
    const game = new RestaurantGame(SEED);
    game.step("sim_start");
    game.step("verify_substitution");

    const result = game.stepEnvelope(
      workerEnvelope(
        game,
        { role: "chef", tool: "prepare", arguments: { orderId: "order-2", substitution: "house-sauce", verified: true } },
        "verified-swap",
      ),
    );
    expect(result.accepted).toBe(true);
    expect(result.state.orders.find((order) => order.id === "order-2")?.status).toBe("preparing");
  });

  it("leaves a ticket the correction does not cover alone", () => {
    const game = new RestaurantGame(SEED);
    game.step("sim_start");
    game.step("verify_substitution");
    expect(game.state().orders.find((order) => order.id === "order-1")?.allergy).toBeUndefined();

    const result = game.stepEnvelope(
      workerEnvelope(game, { role: "chef", tool: "prepare", arguments: { orderId: "order-1", substitution: "house-sauce" } }, "uncovered"),
    );
    expect(result.accepted).toBe(true);
  });

  it("stops the floor seating a party while the hold-the-door correction stands", () => {
    const game = new RestaurantGame(SEED);
    game.step("sim_start");
    for (let tick = 0; tick < 6; tick += 1) game.step("tick");
    game.step("hold_seating");
    // The held door is what puts parties in the queue in the first place.
    for (let tick = 0; tick < 3; tick += 1) game.step("tick");

    const party = game.view().waiting[0];
    const table = game.state().tables.find((candidate) => candidate.status === "empty");
    expect(party).toBeDefined();
    expect(table).toBeDefined();

    for (const role of ["host", "server"] as const) {
      const refused = game.stepEnvelope(
        workerEnvelope(game, { role, tool: "seat", arguments: { tableId: table!.id, partyId: party!.id } }, `seat-${role}`),
      );
      expect(refused.accepted).toBe(false);
      expect(refused.error?.code).toBe("invalid_state");
      expect(refused.error?.retryable).toBe(true);
      expect(refused.error?.message).toContain("hold-the-door");
    }

    expect(game.liftDirective("dir-1").accepted).toBe(true);
    const seated = game.stepEnvelope(
      workerEnvelope(game, { role: "host", tool: "seat", arguments: { tableId: table!.id, partyId: party!.id } }, "seat-after-lift"),
    );
    expect(seated.accepted).toBe(true);
    expect(seated.state.tables.find((candidate) => candidate.id === table!.id)?.status).toBe("occupied");
  });
});

describe("carrying a correction out is credited", () => {
  it("credits correctionUptake to the chef who verifies the covered ticket", () => {
    const game = new RestaurantGame(SEED);
    game.step("sim_start");
    game.step("verify_substitution");
    const issued = game.state().outcomes.correctionUptake;

    game.stepEnvelope(
      workerEnvelope(game, { role: "chef", tool: "prepare", arguments: { orderId: "order-2", verifiedSafe: true } }, "verify-credit"),
    );
    expect(game.state().outcomes.correctionUptake).toBeGreaterThan(issued);
  });

  it("credits correctionUptake to the host who quotes the wait under a held door", () => {
    const game = new RestaurantGame(SEED);
    game.step("sim_start");
    game.step("hold_seating");
    const issued = game.state().outcomes.correctionUptake;

    game.stepEnvelope(
      workerEnvelope(game, { role: "host", tool: "update_guest", arguments: { message: "Twenty minutes, and that is an honest quote." } }, "quote"),
    );
    expect(game.state().outcomes.correctionUptake).toBeGreaterThan(issued);
  });

  // CORRECTIONS_AND_PROBE_CONTRACT.md §1.
  it("raises both metrics when a worker coordinates the ticket a priority correction named", () => {
    const game = new RestaurantGame(SEED);
    game.step("sim_start");
    game.step("prioritize_allergy");
    const before = { ...game.state().outcomes };

    const result = game.stepEnvelope(
      workerEnvelope(game, { role: "supply_lead", tool: "coordinate", arguments: { orderId: "order-2", priority: "high" } }, "coordinate"),
    );
    expect(result.accepted).toBe(true);
    expect(game.state().outcomes.correctionUptake).toBeGreaterThan(before.correctionUptake);
    expect(game.state().outcomes.coordination).toBeGreaterThan(before.coordination);
  });

  it("raises coordination alone when a worker relays an active correction", () => {
    const game = new RestaurantGame(SEED);
    game.step("sim_start");
    game.step("verify_substitution");
    const before = { ...game.state().outcomes };

    const result = game.stepEnvelope(
      workerEnvelope(
        game,
        { role: "chef", tool: "send_message", arguments: { to: "worker-server", text: "Manager's safety call stands: nothing swapped goes out unchecked." } },
        "relay",
      ),
    );
    expect(result.accepted).toBe(true);
    expect(game.state().outcomes.coordination).toBeGreaterThan(before.coordination);
    expect(game.state().outcomes.correctionUptake).toBe(before.correctionUptake);
  });

  it("never moves coordination for work unrelated to a standing correction", () => {
    const game = new RestaurantGame(SEED);
    game.step("sim_start");
    game.step("verify_substitution");
    const before = { ...game.state().outcomes };

    game.stepEnvelope(workerEnvelope(game, { role: "chef", tool: "inspect", arguments: { targetId: "oven-1" } }, "unrelated-inspect"));
    game.stepEnvelope(
      workerEnvelope(game, { role: "chef", tool: "send_message", arguments: { to: "worker-server", text: "Table 1 is two minutes out." } }, "unrelated-message"),
    );
    expect(game.state().outcomes.coordination).toBe(before.coordination);

    const clean = new RestaurantGame(SEED);
    clean.step("sim_start");
    clean.stepEnvelope(
      workerEnvelope(clean, { role: "chef", tool: "send_message", arguments: { to: "worker-server", text: "Priority on the safety of the pace here." } }, "no-directive"),
    );
    expect(clean.state().outcomes.coordination).toBe(0);
  });
});

describe("probeReport(): did the correction stay in its scope?", () => {
  it("is pending until the warming shelf starts running warm", () => {
    const game = new RestaurantGame(SEED);
    game.step("sim_start");
    game.step("verify_substitution");

    const report = game.probeReport();
    expect(report.outcome).toBe("pending");
    expect(report.triggered).toBe(false);
    expect(report.triggeredAtTick).toBeUndefined();
    expect(report.falsePositives).toBe(0);
    expect(report.decisions).toEqual([]);
  });

  // CORRECTIONS_AND_PROBE_CONTRACT.md §2: the trigger firing is what moves this,
  // never how many responses have been recorded.
  it("reads scope_held the instant the trigger fires, with no responses yet", () => {
    const game = new RestaurantGame(SEED);
    playToProbeTrigger(game);

    const report = game.probeReport();
