    expect(report.outcome).toBe("over_generalized");
    expect(report.falsePositives).toBe(1);
    expect(report.decisions.at(-1)).toMatchObject({ falsePositive: true, reason: "halted_service" });
  });

  it("calls the allergy protocol over a warm shelf an over-generalisation", () => {
    const game = new RestaurantGame(SEED);
    playToProbeTrigger(game);

    game.stepEnvelope(
      workerEnvelope(
        game,
        { role: "server", tool: "send_message", arguments: { to: "worker-chef", text: "Running the allergy protocol on every plate off that shelf." } },
        "allergy",
      ),
