it("issues a standing safety correction from the manager's correct tool", () => {
  const game = new RestaurantGame(SEED);
  game.step("sim_start");
  const result = game.submitPlayerIntervention({
    kind: "correction",
    targetRole: "chef",
    text: "Protect safety: verify before substituting.",
  });
  expect(result.accepted).toBe(true);

  const [issued] = game.activeDirectives();
  expect(issued?.category).toBe("safety");
  expect(issued?.note).toBe("Protect safety: verify before substituting.");
  expect(game.directivesFor("chef").map((directive) => directive.id)).toEqual([issued!.id]);
});

it("treats reopening the door as lifting the hold, and journals it as a cleared hold", () => {
  const game = new RestaurantGame(SEED);
  game.step("sim_start");
  game.step("hold_seating");
  expect(game.activeDirectives().map((directive) => directive.category)).toEqual(["pace"]);

  game.step("tick");
  game.step("tick");
  game.step("hold_seating");
  expect(game.state().seatingHeld).toBe(false);
  expect(game.activeDirectives()).toEqual([]);
  expect(game.directivesFor("host", { includeLifted: true })[0]?.liftedAtTick).toBe(2);

  const kinds = game.captureTrace({ runKind: "synthetic" }).events.map((event) => event.kind);
  expect(kinds.filter((kind) => kind === "player_correction")).toHaveLength(1);
  expect(kinds).toContain("hold_cleared");
});

it("journals an explicit lift as a cleared hold rather than a fresh correction", () => {
  const game = new RestaurantGame(SEED);
  game.step("sim_start");
  game.step("verify_substitution");
  expect(game.liftDirective("dir-1").accepted).toBe(true);

  const events = game.captureTrace({ runKind: "synthetic" }).events;
  expect(events.filter((event) => event.kind === "player_correction")).toHaveLength(1);
  expect(events.at(-1)?.kind).toBe("hold_cleared");
});

